// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface InfectionCaseOut {
  case_id: number;
  case_number: string;
  kind: "SurgicalSite" | "CatheterUrinary" | "CentralLineBloodstream" | "VentilatorPneumonia" | "HospitalPneumonia" | "Gastrointestinal" | "SkinSoftTissue" | "Other";
  patient_id: number;
  mrn: string;
  patient_name: string;
  admission_id: number | null;
  admission_number: string | null;
  ward_name: string | null;
  booking_id: number | null;
  booking_number: string | null;
  procedure_name: string | null;
  ssi_depth: "Superficial" | "Deep" | "OrganSpace" | null;
  onset_date: string;
  found_at: "DuringStay" | "Readmission" | "OpdFollowUp" | "Telephone" | "Other";
  organism: string | null;
  description: string;
  status: "Suspected" | "Confirmed" | "Excluded";
  reported_at: string;
  report_stamp: AuthorStampOut;
  decided_at: string | null;
  decision_note: string | null;
  decision_stamp: AuthorStampOut | null;
  row_version: number;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface InfectionCaseIn {
  kind: "SurgicalSite" | "CatheterUrinary" | "CentralLineBloodstream" | "VentilatorPneumonia" | "HospitalPneumonia" | "Gastrointestinal" | "SkinSoftTissue" | "Other";
  /** The patient (GET /patients/search) */
  patient_id?: number | null;
  admission_id?: number | null;
  /** A surgical site infection: the operation (GET /infection/ssi-surveillance) */
  booking_id?: number | null;
  ssi_depth?: "Superficial" | "Deep" | "OrganSpace" | null;
  onset_date: string;
  found_at: "DuringStay" | "Readmission" | "OpdFollowUp" | "Telephone" | "Other";
  organism?: string | null;
  /** The signs, the results, the criteria met */
  description: string;
}

export interface CaseDecisionIn {
  status: "Confirmed" | "Excluded";
  /** The criteria met, or why it is not a healthcare infection */
  note: string;
  ssi_depth?: "Superficial" | "Deep" | "OrganSpace" | null;
  organism?: string | null;
}

/** An operation under surgical site infection surveillance (MSDS COP 50). */
export interface SurveillanceOut {
  booking_id: number;
  booking_number: string;
  procedure_name: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  ot_id: number | null;
  ot_name: string | null;
  primary_surgeon_id: number;
  surgeon_name: string;
  wound_class: "Clean" | "CleanContaminated" | "Contaminated" | "Dirty" | null;
  implant_left: boolean;
  operated_on: string;
  /** ssi_followup_days, or ssi_implant_followup_days with an implant */
  window_days: number;
  /** Days since the operation */
  day: number;
  last_check: string | null;
  checks: number;
  /** A check in the last week of the window or later */
  closing_check: boolean;
  /** A surgical site infection reported for it */
  infection: "Suspected" | "Confirmed" | "Excluded" | null;
  state: "InWindow" | "Due" | "Overdue" | "Complete";
}

/** A person the search found, always as their master record (merged profiles are never hits of their own). */
export interface PatientSearchHitOut {
  patient_id: number;
  /** The newest Patient Photo of the merge chain, for the identity check; null when none was taken (it is optional). GET /patient-documents/{document_id}/download */
  photo_document_id: number | null;
  mrn: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  full_name: string;
  father_or_husband_name: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  dob: string | null;
  age_years: number | null;
  /** When age_years was recorded (the age grows from that date) */
  age_recorded_on: string | null;
  mobile: string | null;
  cnic: string | null;
  /** The Universal Patient Medical Record Number when one was recorded (optional) */
  upmrn: string | null;
  address: string | null;
  emergency_contact_name: string | null;
  emergency_contact_phone: string | null;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  allergies: string | null;
  billing_category: "Cash" | "Panel";
  panel_id: number | null;
  panel_name: string | null;
  panel_member_no: string | null;
  /** Unknown-trauma label, e.g. "Unknown Male 3" */
  temp_identifier: string | null;
  merged_into_id: number | null;
  linked_employee_id: number | null;
  is_deceased: boolean;
  /** The death record (GET /deaths/{death_id}) when the death is recorded */
  death_id: number | null;
  death_at: string | null;
  /** Medico-legal case numbers of this person: show a MEDICO-LEGAL banner when not empty (MSDS 154: the record is clearly so marked) */
  mlc_numbers: string[];
  created_at: string;
  row_version: number;
  outstanding: OutstandingBannerOut;
  /** The profile merged into this record that the search matched when this record itself did not (an old slip's MRN, a trauma label such as "Unknown Male 3", a duplicate's name or numbers): say "Found by MRN-…, merged into this record". Null when this record matched */
  matched_merged_profile: MergedProfileOut | null;
}

/** Outstanding dues of the patient's whole merge chain (workflow sections 1.2 and 1.9). */
export interface OutstandingBannerOut {
  has_outstanding_ar: boolean;
  outstanding_ar_balance: number;
  /** True: reception blocks a new OPD slip unless ER bypass or an override */
  ar_block_applies: boolean;
  /** Show it prominently, e.g. "OUTSTANDING BALANCE: RS. 2,500" */
  banner_text: string | null;
}

/** Another record of the same person, merged into this one (e.g. a trauma registration). */
export interface MergedProfileOut {
  patient_id: number;
  mrn: string;
  full_name: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  temp_identifier: string | null;
}

/** Infection cases — GET /api/v1/infection-cases (who may call: holders of infection.case.report or infection.control.manage or infection.statistics.view). */
export function listCasesInfection(query?: { status?: "Suspected" | "Confirmed" | "Excluded" | null; kind?: "SurgicalSite" | "CatheterUrinary" | "CentralLineBloodstream" | "VentilatorPneumonia" | "HospitalPneumonia" | "Gastrointestinal" | "SkinSoftTissue" | "Other" | null; patient_id?: number | null; booking_id?: number | null; date_from?: string | null; date_to?: string | null; limit?: number }): Promise<InfectionCaseOut[]> {
  return api<InfectionCaseOut[]>("GET", withQuery(`/infection-cases`, query), undefined);
}

/** Report a suspected healthcare-associated infection — POST /api/v1/infection-cases (who may call: holders of infection.case.report or infection.control.manage). */
export function reportCase(body: InfectionCaseIn): Promise<InfectionCaseOut> {
  return api<InfectionCaseOut>("POST", `/infection-cases`, body, { idempotent: true });
}

/** Confirm or exclude a suspected infection — POST /api/v1/infection-cases/{case_id}/decision (who may call: holders of infection.control.manage). */
export function decideCaseInfectionCasesDecision(case_id: number, body: CaseDecisionIn): Promise<InfectionCaseOut> {
  return api<InfectionCaseOut>("POST", `/infection-cases/${case_id}/decision`, body, { idempotent: true });
}

/** Operations under wound surveillance — GET /api/v1/infection/ssi-surveillance (who may call: holders of infection.control.manage or infection.statistics.view). */
export function ssiSurveillance(query?: { state?: string | null; surgeon_id?: number | null; limit?: number }): Promise<SurveillanceOut[]> {
  return api<SurveillanceOut[]>("GET", withQuery(`/infection/ssi-surveillance`, query), undefined);
}

/** Returning-patient lookup by name / phone / CNIC / UPMRN / MRN — GET /api/v1/patients/search (who may call: holders of patient.search). */
export function searchPatients(query: { q: string; limit?: number }): Promise<PatientSearchHitOut[]> {
  return api<PatientSearchHitOut[]>("GET", withQuery(`/patients/search`, query), undefined);
}
